221	
222	
223	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
224	    @Override
225	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
226	        Owner owner = this.clinicService.findOwnerById(ownerId);
227	        if (owner != null) {
228	            Pet pet = owner.getPet(petId);
229	            if (pet != null) {
230	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
231	            }
232	        }
233	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
234	    }
235	
236	    /**
237	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
238	     * The address is normalized in place (so a required-field check that follows rejects an
239	     * address blank after normalization), the required fields are checked, the telephone and
240	     * email are normalized in place, and the resulting owner is rejected when its derived
241	     * identity key already belongs to another owner. Each rule
242	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
243	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
244	     * to be mapped and saved.
245	     *
246	     * @param ownerFieldsDto the submitted owner fields, normalized in place
247	     */
248	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
249	        applyAddress(ownerFieldsDto);
250	        validateRequiredFields(ownerFieldsDto);
251	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
252	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
253	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
254	        rejectDuplicateIdentity(ownerFieldsDto);
255	        rejectCityAtCapacity(ownerFieldsDto.getCity());
256	        rejectDailyLimitExceeded(registrationDate);
257	    }
258	
259	    /**
260	     * Applies an owner's address to the submitted fields, normalizing it in place into the
261	     * canonical form stored and returned for the owner. This is the single intake step that owns
262	     * how a submitted address becomes an owner's stored address: it delegates every transform to
263	     * {@link #normalizeAddress(String)}, the single definition of address normalization, and writes
264	     * the results back onto {@code ownerFieldsDto}.
265	     *
266	     * <p>The structured fields are preferred when supplied: when a non-blank {@code addressLine1}
267	     * is present the two structured lines are normalized in place and the flat {@code address} is
268	     * (re)composed from them — the normalized {@code addressLine1}, with a single space and the
269	     * normalized {@code addressLine2} appended only when an {@code addressLine2} was supplied — so
270	     * every rule that later reads {@code address} sees the structured value. When no structured
271	     * {@code addressLine1} is supplied the flat {@code address} is normalized in place, preserving
272	     * backward compatibility.
273	     *
274	     * <p>It runs ahead of {@link #validateRequiredFields(OwnerFieldsDto)} so an address that is
275	     * blank after normalization in either form is rejected by the required-field check that
276	     * follows. Isolating the step here keeps {@link #prepareNewOwner(OwnerFieldsDto, LocalDate)} a
277	     * list of named intake steps and gives address handling one place to grow.
278	     *
279	     * @param ownerFieldsDto the submitted owner fields, whose address is normalized in place
280	     */
281	    private void applyAddress(OwnerFieldsDto ownerFieldsDto) {
282	        String line1 = ownerFieldsDto.getAddressLine1();
283	        if (line1 != null && !line1.isBlank()) {
284	            String normalizedLine1 = normalizeAddress(line1);
285	            ownerFieldsDto.setAddressLine1(normalizedLine1);
286	            String line2 = ownerFieldsDto.getAddressLine2();
287	            if (line2 != null && !line2.isBlank()) {
288	                String normalizedLine2 = normalizeAddress(line2);
289	                ownerFieldsDto.setAddressLine2(normalizedLine2);
290	                ownerFieldsDto.setAddress(normalizedLine1 + " " + normalizedLine2);
291	            } else {
292	                ownerFieldsDto.setAddressLine2(null);
293	                ownerFieldsDto.setAddress(normalizedLine1);
294	            }
295	        } else {
296	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
297	        }
298	    }
299	
300	    /**
301	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
302	     * falls on a business day. The date supplied on the request is used when present, otherwise the
303	     * server's current date is used. When that effective date lands on a Saturday, Sunday or listed
304	     * public holiday it is rolled forward to the next non-holiday business day; a non-holiday weekday
305	     * is left unchanged. This single adjusted date
306	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
307	     * membership number's year segment, the per-day create limit) is computed against.
308	     *
309	     * A supplied registration date later than the server's current date is rejected with an
310	     * {@link InvalidFieldsException}, which the exception advice renders as a 400 Bad Request.
311	     *
312	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
313	     * @return the effective registration date rolled forward to the next business day
314	     */
315	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
316	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
317	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
318	            throw new InvalidFieldsException(List.of("registrationDate"));
319	        }
320	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
321	        return toBusinessDay(effective);
322	    }
323	
324	    /**
325	     * The fixed public holidays the business-day roll skips. A date landing on any of these is
326	     * advanced, along with weekends, until it reaches the next non-holiday business day.
327	     */
328	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
329	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
330	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
331	        LocalDate.parse("2026-12-28"));
332	
333	    /**
334	     * Rolls a date forward to the next business day: a Saturday, Sunday or listed public holiday is
335	     * advanced one day at a time until it reaches a weekday that is not a public holiday, while a
336	     * date already on such a business day is returned unchanged.
337	     *
338	     * @param date the date to adjust
339	     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
340	     */
341	    private LocalDate toBusinessDay(LocalDate date) {
342	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
343	                || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
344	                || PUBLIC_HOLIDAYS.contains(date)) {
345	            date = date.plusDays(1);
346	        }
347	        return date;
348	    }
349	
350	    /**
351	     * The maximum number of owners that may be created on a single day. Once this many owners
352	     * already carry today's {@code registrationDate}, no further owner may be created today.
353	     */
354	    private static final long DAILY_OWNER_LIMIT = 100L;
355	
356	    /**
357	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
358	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
359	     * date the new owner would be stored with, so owners are capped per business day. When the limit
360	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
361	     * advice renders as a 429 Too Many Requests response.
362	     *
363	     * @param registrationDate the adjusted business-day registration date of the owner being created
364	     */
365	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
366	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
367	            throw new DailyOwnerLimitExceededException(registrationDate);
368	        }
369	    }
370	
371	    /**
372	     * Counts the existing owners whose adjusted business-day {@code registrationDate} equals the
373	     * given date. This is the single definition of the per-day owner count, shared by the per-day
374	     * create limit ({@link #rejectDailyLimitExceeded(LocalDate)}) and the bulk-signup warning
375	     * ({@link #bulkSignupWarning(LocalDate)}), so both accumulate owners against a day identically.
376	     *
377	     * @param registrationDate the adjusted business-day registration date to count owners against
378	     * @return the number of existing owners carrying that registration date
379	     */
380	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
381	        return this.clinicService.findAllOwners().stream()
382	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
383	            .count();
384	    }
385	
386	    /**
387	     * The number of owners that may carry a single day's {@code registrationDate} before that day
388	     * is flagged as a bulk-signup day. Once more than this many owners share a registration date,
389	     * the create and read responses report {@code bulkSignupWarning} true for that date.
390	     */
391	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
392	
393	    /**
394	     * Reports whether the given business-day {@code registrationDate} is a bulk-signup day, i.e.
395	     * whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry that date. The
396	     * count is taken against the same adjusted date owners are stored with, mirroring the
397	     * per-day create-limit accumulation. A {@code null} date is never a bulk-signup day.
398	     *
399	     * @param registrationDate the adjusted business-day registration date to test, or {@code null}
400	     * @return {@code true} when more than 80 owners share the date, otherwise {@code false}
401	     */
402	    private boolean bulkSignupWarning(LocalDate registrationDate) {
403	        if (registrationDate == null) {
404	            return false;
405	        }
406	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
407	    }
408	
409	    /**
410	     * The maximum number of owners a single city may hold. Once a city already contains this
411	     * many owners, no further owner may be created in it.
412	     */
413	    private static final long CITY_OWNER_CAPACITY = 50L;
414	
415	    /**
416	     * Rejects a new owner whose city already contains {@link #CITY_OWNER_CAPACITY} or more owners.
417	     * Cities are compared case-insensitively, consistent with how per-city owners are counted
418	     * elsewhere. When the city is at capacity a {@link CityCapacityExceededException} is thrown,
419	     * which the exception advice renders as a 409 Conflict response.
420	     *
421	     * @param city the city of the owner being created
422	     */
423	    private void rejectCityAtCapacity(String city) {
424	        long count = this.clinicService.findAllOwners().stream()
425	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
426	            .count();
427	        if (count >= CITY_OWNER_CAPACITY) {
428	            throw new CityCapacityExceededException(city);
429	        }
430	    }
431	
432	    /**
433	     * Builds the customer code assigned to a newly created owner. The code is formatted as
434	     * {@code '<REGION>-<HASH8>'}, where {@code REGION} is the owner's canonical region (see
435	     * {@link Owner#getRegion()}), rendered {@code 'UNKNOWN'} when the owner has no known region,
436	     * and {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest over the
437	     * owner's normalized E.164 {@code telephone} concatenated with its {@code lastName}. The code
438	     * carries no sequence number, so two owners sharing a region, telephone and last name resolve to
439	     * the same code. The whole owner is taken so the code is derived from whichever of its fields the
440	     * identity scheme needs.
441	     *
442	     * @param owner the owner being created, whose fields the code is derived from
443	     * @return the formatted customer code
444	     */
445	    private String customerCodeFor(Owner owner) {
446	        String region = owner.getRegion();
447	        String regionCode = region != null ? region : "UNKNOWN";
448	        String hash8 = shaHex(owner.getTelephone() + owner.getLastName(), 8);
449	        return deduplicateCustomerCode(regionCode + "-" + hash8);
450	    }
451	
452	    /**
453	     * Ensures the computed {@code customerCode} is unique across existing owners. When the given base
454	     * code collides with an existing owner's {@code customerCode}, {@code '-<n>'} is appended with the
455	     * smallest {@code n} of 2 or more that yields a code no existing owner already carries.
456	     *
457	     * @param baseCode the customer code computed for the owner being created
458	     * @return the base code when it is already unique, otherwise the de-duplicated code
459	     */
460	    private String deduplicateCustomerCode(String baseCode) {
461	        Set<String> existing = this.clinicService.findAllOwners().stream()
462	            .map(Owner::getCustomerCode)
463	            .filter(Objects::nonNull)
464	            .collect(Collectors.toSet());
465	        if (!existing.contains(baseCode)) {
466	            return baseCode;
467	        }
468	        int n = 2;
469	        while (existing.contains(baseCode + "-" + n)) {
470	            n++;
471	        }
472	        return baseCode + "-" + n;
473	    }
474	
475	    /**
476	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
477	     * with the owner being created, compared case-insensitively. The count is taken before the
478	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
479	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
480	     *
481	     * @param firstName the first name of the owner being created
482	     * @param lastName the last name of the owner being created
483	     * @return the number of pre-existing owners sharing the same first and last name
484	     */
485	    private int countNamesakes(String firstName, String lastName) {
486	        return (int) this.clinicService.findAllOwners().stream()
487	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
488	                && lastName.equalsIgnoreCase(existing.getLastName()))
489	            .count();
490	    }
491	
492	    /**
493	     * Flags a newly created owner as a possible (soft) duplicate. Reaching this point means the
494	     * owner already cleared {@link #rejectDuplicateIdentity(OwnerFieldsDto)}, so it is not a hard
495	     * household duplicate. A member that declared its household via {@code sharesHousehold} is a
496	     * deliberate addition to a known household, not a suspected duplicate, so it is never flagged.
497	     * Otherwise it is a possible duplicate when an existing owner shares its {@code lastName}
498	     * (compared case-insensitively) and its {@code postcode} while carrying a different (normalized)
499	     * {@code telephone}. When such an owner is found, {@code possibleDuplicate} is set {@code true}
500	     * and {@code possibleDuplicateOf} to the matching owner's id; otherwise {@code possibleDuplicate}
501	     * is set {@code false} and no matching id is recorded. An owner without a postcode can share no
502	     * postcode and is never a possible duplicate.
503	     *
504	     * @param owner the owner being created, already carrying its normalized telephone and postcode
505	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
506	     */
507	    private void applyPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
508	        owner.setPossibleDuplicate(false);
509	        owner.setPossibleDuplicateOf(null);
510	        if (sharesHousehold(ownerFieldsDto)) {
511	            return;
512	        }
513	        findPossibleDuplicate(owner).ifPresent(existing -> {
514	            owner.setPossibleDuplicate(true);
515	            owner.setPossibleDuplicateOf(existing.getId());
516	        });
517	    }
518	
519	    /**
520	     * Finds the existing owner, if any, that makes the given newly created owner a possible (soft)
521	     * duplicate: an owner sharing its {@code lastName} (compared case-insensitively) and its
522	     * {@code postcode} while carrying a different (normalized) {@code telephone}. This is the single
523	     * definition of the soft-duplicate match; {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)} only records the
524	     * outcome on the owner. An owner without a postcode can share no postcode and matches nothing, so
525	     * {@link java.util.Optional#empty()} is returned.
526	     *
527	     * @param owner the owner being created, already carrying its normalized telephone and postcode
528	     * @return the matching existing owner, or {@link java.util.Optional#empty()} when none matches
529	     */
530	    private java.util.Optional<Owner> findPossibleDuplicate(Owner owner) {
531	        if (owner.getPostcode() == null) {
532	            return java.util.Optional.empty();
533	        }
534	        return this.clinicService.findAllOwners().stream()
535	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
536	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName())
537	                && owner.getPostcode().equals(existing.getPostcode())
538	                && !owner.getTelephone().equals(existing.getTelephone()))
539	            .findFirst();
540	    }
541	
542	    /**
543	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
544	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
545	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
546	     * the names of every offending field, which the exception advice renders as a 400 response
547	     * with an {@code errors} array.
548	     *
549	     * @param ownerFieldsDto the submitted owner fields
550	     */
551	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
552	        List<String> missing = new ArrayList<>();
553	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
554	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
555	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
556	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
557	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
558	        if (!missing.isEmpty()) {
559	            throw new RequiredFieldsMissingException(missing);
560	        }
561	    }
562	
563	    private void addIfBlank(List<String> missing, String fieldName, String value) {
564	        if (value == null || value.isBlank()) {
565	            missing.add(fieldName);
566	        }
567	    }
568	
569	    /**
570	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
571	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
572	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
573	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
574	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
575	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
576	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
577	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
578	     *
579	     * @param telephone the submitted telephone value
580	     * @return the normalized E.164 telephone
581	     */
582	    private String normalizeTelephone(String telephone) {
583	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
584	        String e164;
585	        if (cleaned.startsWith("+")) {
586	            e164 = "+" + cleaned.substring(1);
587	        } else {
588	            String national = cleaned;
589	            if (national.startsWith("0")) {
590	                national = national.substring(1);
591	            }
592	            e164 = "+61" + national;
593	        }
594	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
595	            throw new InvalidFieldsException(List.of("telephone"));
596	        }
597	        validateNationalNumberLength(e164);
598	        return e164;
599	    }
600	
601	    /**
602	     * Validates the national-number length of an already syntactically valid E.164 telephone
603	     * against its country code. When the number carries a country code this application recognizes
604	     * (see {@link Owner#countryCodeOf(String)}) the digits following that code must have exactly the
605	     * length that code admits ({@code '+61'} => 9 national digits, {@code '+1'} => 10, see
606	     * {@link Owner#nationalNumberLength(String)}). When the country code is recognized but the
607	     * national number is the wrong length an {@link InvalidFieldsException} is thrown, which the
608	     * exception advice renders as a 400 response naming the {@code telephone} field. A country code
609	     * that is not recognized carries no per-country length rule and is left to the general
610	     * 8-to-15-digit E.164 check.
611	     *
612	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
613	     */
614	    private void validateNationalNumberLength(String e164) {
615	        String countryCode = Owner.countryCodeOf(e164);
616	        if (countryCode == null) {
617	            return;
618	        }
619	        int nationalLength = e164.length() - 1 - countryCode.length();
620	        if (nationalLength != Owner.nationalNumberLength(countryCode)) {
621	            throw new InvalidFieldsException(List.of("telephone"));
622	        }
623	    }
624	
625	    /**
626	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
627	     * and a domain containing at least one dot, none of the parts holding whitespace or a
628	     * second {@code @}.
629	     */
630	    private static final java.util.regex.Pattern EMAIL_PATTERN =
631	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
632	
633	    /**
634	     * Disposable email domains an owner may not register with. An email whose domain (compared
635	     * case-insensitively) is one of these is rejected, since it identifies a throwaway mailbox.
636	     */
637	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
638	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
639	
640	    /**
641	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
642	     * accepted and returned unchanged. When present it must be a syntactically valid address
643	     * whose domain is not on the disposable-domain blocklist (see
644	     * {@link #DISPOSABLE_EMAIL_DOMAINS}); the value is stored and returned lower-cased. When
645	     * present but syntactically invalid or on a disposable domain an
646	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
647	     * response naming the {@code email} field.
648	     *
649	     * @param email the submitted email value, or {@code null} when omitted
650	     * @return the lower-cased email, or {@code null} when none was supplied
651	     */
652	    private String normalizeEmail(String email) {
653	        if (email == null) {
654	            return null;
655	        }
656	        String trimmed = email.trim();
657	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
658	            throw new InvalidFieldsException(List.of("email"));
659	        }
660	        String domain = trimmed.substring(trimmed.lastIndexOf('@') + 1).toLowerCase(java.util.Locale.ROOT);
661	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
662	            throw new InvalidFieldsException(List.of("email"));
663	        }
664	        return canonicalEmail(trimmed);
665	    }
666	
667	    /**
668	     * Reduces an email to the canonical form used both to store it and to compare it against
669	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
670	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
671	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
672	     * value read back off an existing owner without risk of rejecting it. This is the single
673	     * definition of email identity: two emails denote the same address exactly when they
674	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
675	     * an email already on an existing owner can be compared for equality after both pass through
676	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
677	     *
678	     * @param email the email to canonicalize, or {@code null} when none was supplied
679	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
680	     */
681	    private String canonicalEmail(String email) {
682	        if (email == null) {
683	            return null;
684	        }
685	        return email.trim().toLowerCase(java.util.Locale.ROOT);
686	    }
687	
688	    /**
689	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
690	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
691	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
692	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
693	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
694	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
695	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
696	     * 400 response naming the {@code postcode} field.
697	     *
698	     * @param postcode the submitted postcode, or {@code null} when omitted
699	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
700	     */
701	    private void validatePostcode(String postcode, String city) {
702	        if (postcode == null) {
703	            return;
704	        }
705	        if (!postcode.matches("^[0-9]{4}$")) {
706	            throw new InvalidFieldsException(List.of("postcode"));
707	        }
708	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
709	        if (range != null) {
710	            int value = Integer.parseInt(postcode);
711	            if (value < range[0] || value > range[1]) {
712	                throw new InvalidFieldsException(List.of("postcode"));
713	            }
714	        }
715	    }
716	
717	    /**
718	     * Rejects a new owner that would join a household already occupied by an existing owner. The
719	     * household is keyed on {@code (lastName, postcode)} and identified by the deterministic
720	     * {@code householdId} the owner would receive (see {@link #householdIdFor(String, String)}), so
721	     * two owners sharing a last name and postcode belong to the same household. When any existing
722	     * owner already carries that household identifier the new owner is a household duplicate and a
723	     * {@link DuplicateIdentityException} is thrown, which the exception advice renders as a 409
724	     * Conflict response. Setting {@code sharesHousehold} declares the owner a deliberate member of
725	     * that household and bypasses this block, so it is created rather than rejected. An owner without
726	     * a postcode belongs to no shared household and is never a household duplicate.
727	     *
728	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
729	     */
730	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
731	        if (sharesHousehold(ownerFieldsDto)) {
732	            return;
733	        }
734	        String householdId = householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
735	        if (householdId == null) {
736	            return;
737	        }
738	        boolean taken = this.clinicService.findAllOwners().stream()
739	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
740	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
741	        if (taken) {
742	            throw new DuplicateIdentityException(householdId);
743	        }
744	    }
745	
746	    /**
747	     * Assigns the deterministic shared {@code householdId} to a newly created owner. The identifier
748	     * is derived from the owner's household identity — its {@code lastName} and {@code postcode} (see
749	     * {@link #householdIdFor(String, String)}) — so every owner sharing a last name and postcode
750	     * resolves to the same stable value automatically, without any explicit linking. An owner without
751	     * a postcode belongs to no shared household and is left without a household identifier.
752	     *
753	     * @param owner the newly created owner, mutated in place with its household identifier
754	     */
755	    private void assignHousehold(Owner owner) {
756	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
757	    }
758	
759	    /**
760	     * Reports whether a submitted owner opted into sharing a household, i.e. whether its request
761	     * carried {@code sharesHousehold} set to {@code true}. A {@code null} or {@code false} flag is
762	     * not opting in. This is the single reading of the {@code sharesHousehold} intent, shared by
763	     * every rule that treats a declared household member differently from an independent owner.
764	     *
765	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
766	     * @return {@code true} when the request opted into sharing a household
767	     */
768	    private boolean sharesHousehold(OwnerFieldsDto ownerFieldsDto) {
769	        return Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
770	    }
771	
772	    /**
773	     * Derives the stable {@code householdId} shared by every owner in the household identified by
774	     * the given {@code lastName} and {@code postcode}. The household is keyed on {@code (lastName,
775	     * postcode)}: the normalized last name and the postcode are hashed with SHA-256 and the leading
776	     * 12 hex characters of the digest form the identifier, so any two owners sharing a last name and
777	     * postcode — regardless of creation order or address — resolve to the same identifier
778	     * automatically. An owner without a postcode belongs to no shared household, so {@code null} is
779	     * returned.
780	     *
781	     * @param lastName the household's last name
782	     * @param postcode the household's postcode, or {@code null} when the owner has none
783	     * @return the deterministic household identifier, or {@code null} when {@code postcode} is {@code null}
784	     */
785	    private String householdIdFor(String lastName, String postcode) {
786	        if (postcode == null) {
787	            return null;
788	        }
789	        return shaHex(householdKey(lastName, postcode), 12);
790	    }
791	
792	    /**
793	     * Builds the canonical household key that identifies the household a {@code lastName} and
794	     * {@code postcode} belong to: the normalized last name (case-insensitive, with collapsed
795	     * whitespace) joined to the postcode by {@code '|'}. This is the single definition of which
796	     * owner fields make up a household and how they are normalized;
797	     * {@link #householdIdFor(String, String)} hashes this key into the stored identifier, so any two
798	     * owners in the same household resolve to the same key and therefore the same identifier.
799	     *
800	     * @param lastName the household's last name
801	     * @param postcode the household's postcode
802	     * @return the normalized household key
803	     */
804	    private String householdKey(String lastName, String postcode) {
805	        return collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|" + postcode;
806	    }
807	
808	    /**
809	     * Computes the upper-case hex SHA-256 digest of a string, truncated to its first
810	     * {@code hexChars} characters. The input is hashed as UTF-8 bytes and each digest byte is
811	     * rendered as two upper-case hex digits, so {@code hexChars} characters cover the leading
812	     * {@code ceil(hexChars / 2)} bytes of the digest. This is the single definition of the
813	     * SHA-256 hex derivation shared by every rule that hashes owner fields (for example the
814	     * household identifier). SHA-256 is a required platform algorithm; were it ever unavailable
815	     * an {@link IllegalStateException} is thrown.
816	     *
817	     * @param input the string to hash
818	     * @param hexChars the number of leading upper-case hex characters to return
819	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest
820	     */
821	    private String shaHex(String input, int hexChars) {
822	        try {
823	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
824	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
825	            StringBuilder sb = new StringBuilder();
826	            for (int i = 0; i < digest.length && sb.length() < hexChars; i++) {
827	                sb.append(String.format("%02X", digest[i]));
828	            }
829	            return sb.substring(0, hexChars);
830	        }
831	        catch (java.security.NoSuchAlgorithmException e) {
832	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
833	        }
834	    }
835	
836	    /**
837	     * Counts the owners that belong to the household identified by the given {@code householdId},
838	     * i.e. every owner carrying that exact identifier. The count is taken against the current set
839	     * of owners, so after a create it reflects the household's size including the newly persisted
840	     * owner. An owner without a household (a {@code null} identifier) belongs to no shared
841	     * household and yields {@code 0}.
842	     *
843	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
844	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
845	     */
846	    private int countHouseholdMembers(String householdId) {
847	        if (householdId == null) {
848	            return 0;
849	        }
850	        return (int) this.clinicService.findAllOwners().stream()
851	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
852	            .count();
853	    }
854	
855	    /**
856	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
857	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
858	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
859	     *
860	     * @param value the value to collapse, or {@code null}
861	     * @return the whitespace-collapsed value, never {@code null}
862	     */
863	    private String collapseWhitespace(String value) {
864	        if (value == null) {
865	            return "";
866	        }
867	        return value.trim().replaceAll("\\s+", " ");
868	    }
869	
870	    /**
871	     * Common street-type abbreviations expanded during address normalization, keyed by their
872	     * upper-cased token.
873	     */
874	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
875	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
876	
877	    /**
878	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
879	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
880	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
881	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
882	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
883	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
884	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
885	     * everywhere an address is stored or compared.
886	     *
887	     * @param address the submitted address value, or {@code null}
888	     * @return the normalized address, never {@code null}
889	     */
890	    private String normalizeAddress(String address) {
891	        if (address == null) {
892	            return "";
893	        }
894	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
895	        if (collapsed.isEmpty()) {
896	            return "";
897	        }
898	        String[] tokens = collapsed.split(" ");
899	        StringBuilder sb = new StringBuilder(collapsed.length());
900	        for (int i = 0; i < tokens.length; i++) {
901	            if (i > 0) {
902	                sb.append(' ');
903	            }
904	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
905	        }
906	        return sb.toString();
907	    }
908	}
